solutions.naive:
class Solution:
    def minRemoveToMakeValid(self, s: str) -> str:
        stack = []
        remove = set()
        for i, ch in enumerate(s):
            if ch == '(':
                stack.append(i)
            elif ch == ')':
                if stack:
                    stack.pop()
                else:
                    remove.add(i)
        remove.update(stack)
        return ''.join(ch for i, ch in enumerate(s) if i not in remove)

solutions.better:
class Solution:
    def minRemoveToMakeValid(self, s: str) -> str:
        first = []
        balance = 0
        for ch in s:
            if ch == '(':
                balance += 1
                first.append(ch)
            elif ch == ')':
                if balance:
                    balance -= 1
                    first.append(ch)
            else:
                first.append(ch)
        second = []
        opens_to_skip = balance
        for ch in reversed(first):
            if ch == '(' and opens_to_skip:
                opens_to_skip -= 1
            else:
                second.append(ch)
        return ''.join(reversed(second))

