class Solution:
    def minRemoveToMakeValid(self, s: str) -> str:
        out = []
        opens = []
        for ch in s:
            if ch == '(':
                opens.append(len(out))
                out.append(ch)
            elif ch == ')':
                if opens:
                    opens.pop()
                    out.append(ch)
            else:
                out.append(ch)
        bad = set(opens)
        return ''.join(ch for i, ch in enumerate(out) if i not in bad)

